// Generated by jacq — kernel `matmul` (matmul: C[M,K] = sum_n A[M,N] * B[N,K]).
// WMMA tensor-core variant (nvcuda::wmma, fp16 in / fp32 accumulate, direct global loads).
// One warp per 16x16 output tile; grid = (K/16) x (M/16). Regenerate; do not hand-edit.
#include <mma.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
using namespace nvcuda;

#define CUDA_CHECK(call) do { \
    cudaError_t err__ = (call); \
    if (err__ != cudaSuccess) { fprintf(stderr, "CUDA error %s at %s:%d\n", cudaGetErrorString(err__), __FILE__, __LINE__); exit(1); } \
} while (0)

static constexpr int M = 256;  // M
static constexpr int N = 128;  // N: contraction
static constexpr int K = 64;  // K

__global__ void matmul_kernel(const __half* A, const __half* B, float* C) {
    // WMMA fragment declarations — shared substrate for all pipeline stages.
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> frag_a;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> frag_b;
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> frag_acc;
    wmma::fill_fragment(frag_acc, 0.0f);  // zero accumulator for kernel `matmul`
    // K-loop: step over the contraction axis (jacq-N) in tiles of 16 (pipeline_stages=1).
    int warp_row = (blockIdx.y * 1) * 16;  // first output row of this warp (M-axis)
    int warp_col = (blockIdx.x * 1) * 16;  // first output col of this warp (K-axis)
    for (int k_base = 0; k_base < N; k_base += 16) {
        // Load A tile: A[warp_row .. +16][k_base .. +16], row-major ld = N.
        wmma::load_matrix_sync(frag_a, A + (size_t)warp_row * N + k_base, N);
        // Load B tile: B[k_base .. +16][warp_col .. +16], row-major ld = K.
        wmma::load_matrix_sync(frag_b, B + (size_t)k_base * K + warp_col, K);
        wmma::mma_sync(frag_acc, frag_a, frag_b, frag_acc);
    }
    // Store accumulator directly to C[warp_row..+16][warp_col..+16], row-major ld = K.
    wmma::store_matrix_sync(C + (size_t)warp_row * K + warp_col, frag_acc, K, wmma::mem_row_major);
}

static __half* load_half(const char* path, size_t count) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    __half* host = (__half*)malloc(count * sizeof(__half));
    size_t rd = fread(host, sizeof(__half), count, f);
    if (rd != count) { fprintf(stderr, "short read %s: %zu/%zu\n", path, rd, count); exit(1); }
    fclose(f);
    __half* dev;
    CUDA_CHECK(cudaMalloc(&dev, count * sizeof(__half)));
    CUDA_CHECK(cudaMemcpy(dev, host, count * sizeof(__half), cudaMemcpyHostToDevice));
    free(host);
    return dev;
}

int main(int argc, char** argv) {
    if (argc < 4) {
        fprintf(stderr, "usage: %s <A.bin [M*N fp16]> <B.bin [N*K fp16]> <C.bin [M*K fp32 out]>\n", argv[0]);
        return 1;
    }
    __half* dA = load_half(argv[1], (size_t)M * N);
    __half* dB = load_half(argv[2], (size_t)N * K);
    float* dC;
    CUDA_CHECK(cudaMalloc(&dC, (size_t)M * K * sizeof(float)));

    // Grid: (N/16) blocks in x (cols), (M/16) blocks in y (rows); 32 threads/block (1 warp).
    dim3 grid((K + 15) / 16, (M + 15) / 16);
    dim3 block(32);  // exactly one warp
    matmul_kernel<<<grid, block>>>(dA, dB, dC);
    CUDA_CHECK(cudaGetLastError());

    float* hC = (float*)malloc((size_t)M * K * sizeof(float));
    CUDA_CHECK(cudaMemcpy(hC, dC, (size_t)M * K * sizeof(float), cudaMemcpyDeviceToHost));
    FILE* out = fopen(argv[3], "wb");
    if (!out) { fprintf(stderr, "cannot write %s\n", argv[3]); return 1; }
    fwrite(hC, sizeof(float), (size_t)M * K, out);
    fclose(out);
    printf("C[0:8] =");
    for (int i = 0; i < 8 && i < M * K; ++i) printf(" %.4f", hC[i]);
    printf("\n");
    return 0;
}
